draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // cloud
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 100, H / 2 + Math.cos(t) * 50, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // bird
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t * 2) * 150, H / 2 + Math.cos(t * 2) * 100, 10, 0, 2 * Math.PI);
  ctx.stroke();

  // tree
  ctx.beginPath();
  ctx.moveTo(W / 2 + 100, H);
  ctx.lineTo(W / 2 + 100, H - 100);
  ctx.stroke();

  // leaves
  ctx.beginPath();
  ctx.arc(W / 2 + 100, H - 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 100 + Math.sin(t) * 20, H - 100 + Math.cos(t) * 20, 10, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
